void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;


    float roll = (iMouse.x / iResolution.x - 0.5) * 2.0;
    float pitch = (iMouse.y / iResolution.y - 0.5) * 2.0;
    float speed = 0.5;


    uv = mat2(cos(roll), -sin(roll), sin(roll), cos(roll)) * uv;
    uv.y += pitch;


    float height = sin(uv.x * 10.0 + iTime * speed) * cos(uv.y * 10.0);


    vec3 skyColor = vec3(0.2, 0.6, 0.8);
    vec3 groundColor = vec3(0.0, 0.3, 0.3);


    float v = uv.y - height;
    vec3 color = mix(groundColor, skyColor, smoothstep(-1., 1., v/fwidth(v) ));

    fragColor = vec4(color, 1.0);
}
